package com.gophisb.houd11;
import android.app.*;import android.content.*;import android.os.*;
public class AdhanReceiver extends BroadcastReceiver{
 static final String ACTION="com.gophisb.houd11.PLAY_ADHAN";
 @Override public void onReceive(Context c,Intent i){ String action=i.getAction(); if(Intent.ACTION_BOOT_COMPLETED.equals(action)||Intent.ACTION_TIME_CHANGED.equals(action)||Intent.ACTION_TIMEZONE_CHANGED.equals(action)){ android.content.SharedPreferences sp=c.getSharedPreferences("adhan_schedule",0); long now=System.currentTimeMillis(); for(String p:new String[]{"fajr","dhuhr","asr","maghrib","isha"}){long t=sp.getLong(p,0L); if(t>0L){if(t<=now)t+=24L*60L*60L*1000L; schedule(c,p,t);}} return;} long fired=System.currentTimeMillis(); AdhanReceiver.schedule(c,i.getStringExtra("prayer"),fired+24L*60L*60L*1000L); Intent s=new Intent(c,AdhanService.class).setAction(AdhanService.ACTION_PLAY);if(Build.VERSION.SDK_INT>=26)c.startForegroundService(s);else c.startService(s);}
 static void schedule(Context c,String p,long t){if(t<=System.currentTimeMillis())return; c.getSharedPreferences("adhan_schedule",0).edit().putLong(p,t).apply();AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);Intent i=new Intent(c,AdhanReceiver.class).setAction(ACTION).putExtra("prayer",p);int id=Math.abs((p+"-"+(t/86400000L)).hashCode());PendingIntent pi=PendingIntent.getBroadcast(c,id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);if(Build.VERSION.SDK_INT>=31&&!am.canScheduleExactAlarms())return;if(Build.VERSION.SDK_INT>=23)am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,t,pi);else am.setExact(AlarmManager.RTC_WAKEUP,t,pi);}
}